// The README's "by the numbers" card, drawn from the same measurements as the
// sentences around it.
//
// A picture of a number is still a claim about the code, and an image is the
// easiest place for a stale one to hide: nobody greps a drawing. So the card is
// generated by readme-numbers.mjs from what it measured, and `readme:check`
// fails when the file on disk is not what the code would draw today.
//
// It carries its own dark ground rather than following the reader's theme:
// GitHub shows an <img> on white and on near-black, and a card that is the same
// on both reads as deliberate on both.

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const comma = (n) => (typeof n === 'number' ? n.toLocaleString('en-US') : n);

const W = 1200;
const COLS = 4;
const TILE_W = 270;
const TILE_H = 122;
const GAP = 16;
const LEFT = (W - (COLS * TILE_W + (COLS - 1) * GAP)) / 2;
const TOP = 132;

const SANS = "'Segoe UI', 'Helvetica Neue', Helvetica, Arial, sans-serif";
const MONO = "'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace";

/** @param {object} f the facts readme-numbers.mjs measured */
export function numbersSvg(f) {
  const tiles = [
    [f.departments, 'departments', `in ${f.divisions} divisions`, '#4fe3f0'],
    [f.relationships, 'relationships', 'declared, drawn, audited', '#a98bff'],
    [f.agents, 'AI employees', 'seeded; departments hire more', '#f6b64c'],
    [f.routes, 'API routes', 'one table, one resolver', '#5aa8ff'],
    [f.permissions, 'permissions', 'atomic; view, manage, irreversible', '#ff6fae'],
    [f.tests, 'tests', `in ${f.testFiles} files, no network`, '#45d49a'],
    [f.liveSources, 'live public sources', 'keyless, each through the gate', '#4fe3f0'],
    [f.tables, 'tables', 'one SQLite file', '#f6b64c'],
    [`${f.hostedProviders} + ${f.localProviders}`, 'AI providers', 'hosted + on this machine', '#a98bff'],
    [f.modules, 'server modules', `${comma(Math.round(f.srcLines / 1000))}k lines, no build step`, '#5aa8ff'],
    [1, 'dependency', '@anthropic-ai/sdk — the rest is Node', '#45d49a'],
    [0, 'external requests', 'from the console — checked', '#ff6fae'],
  ];
  const rows = Math.ceil(tiles.length / COLS);
  const H = TOP + rows * TILE_H + (rows - 1) * GAP + 62;

  const cells = tiles.map(([value, label, sub, accent], i) => {
    const x = LEFT + (i % COLS) * (TILE_W + GAP);
    const y = TOP + Math.floor(i / COLS) * (TILE_H + GAP);
    return `
  <g transform="translate(${x} ${y})">
    <rect width="${TILE_W}" height="${TILE_H}" rx="14" fill="url(#tile)" stroke="#1d2a44"/>
    <rect x="0" y="22" width="3" height="40" rx="1.5" fill="${accent}"/>
    <text x="22" y="62" font-family="${SANS}" font-size="44" font-weight="300" fill="${accent}">${esc(comma(value))}</text>
    <text x="22" y="88" font-family="${MONO}" font-size="12.5" letter-spacing="1.6" fill="#d8e3f5">${esc(label.toUpperCase())}</text>
    <text x="22" y="108" font-family="${SANS}" font-size="12.5" fill="#7d8aa5">${esc(sub)}</text>
  </g>`;
  }).join('');

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-labelledby="t d">
  <title id="t">AlphaCore by the numbers</title>
  <desc id="d">${esc(tiles.map(([v, l]) => `${comma(v)} ${l}`).join(', '))}. Measured from the code by npm run readme.</desc>
  <defs>
    <radialGradient id="glow" cx="0.86" cy="0.08" r="0.7">
      <stop offset="0" stop-color="#1b4f73" stop-opacity="0.75"/>
      <stop offset="1" stop-color="#070b14" stop-opacity="0"/>
    </radialGradient>
    <linearGradient id="tile" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#101a2e"/>
      <stop offset="1" stop-color="#0b1222"/>
    </linearGradient>
    <pattern id="dots" width="22" height="22" patternUnits="userSpaceOnUse">
      <circle cx="1" cy="1" r="1" fill="#1a2640"/>
    </pattern>
  </defs>
  <rect width="${W}" height="${H}" rx="22" fill="#070b14"/>
  <rect width="${W}" height="${H}" rx="22" fill="url(#dots)"/>
  <rect width="${W}" height="${H}" rx="22" fill="url(#glow)"/>
  <g fill="none" stroke="#4fe3f0" stroke-opacity="0.16">
    <circle cx="1060" cy="62" r="120"/>
    <circle cx="1060" cy="62" r="190" stroke-dasharray="2 7"/>
  </g>
  <circle cx="1170" cy="44" r="4" fill="#f6b64c"/>
  <circle cx="944" cy="104" r="3" fill="#4fe3f0"/>
  <text x="${LEFT}" y="58" font-family="${MONO}" font-size="13" letter-spacing="4" fill="#4fe3f0">ALPHACORE · BY THE NUMBERS</text>
  <text x="${LEFT}" y="98" font-family="${SANS}" font-size="30" font-weight="300" fill="#eef3fb">One process. One SQLite file. A whole company.</text>${cells}
  <text x="${LEFT}" y="${H - 26}" font-family="${MONO}" font-size="12" letter-spacing="1" fill="#55627c">Measured from the code by npm run readme — CI fails when this drawing and the code disagree.</text>
</svg>
`;
}
